instruction:
Refactor this code by replacing the vague variable names with names that describe the domain:

def calc(d):
    tmp = 0
    for x in d:
        tmp = tmp + x['p'] * x['q']
    if tmp > 100:
        tmp = tmp * 0.85
    return tmp

output:
def calculate_order_total(line_items):
    subtotal = 0
    for item in line_items:
        subtotal += item['p'] * item['q']
    if subtotal > 100:
        subtotal = subtotal * 0.85
    return subtotal

What changed: d/x/tmp became line_items/subtotal, and the function name says what it computes; the field keys p/q should be renamed price/qty next.

instruction:
Refactor this code by giving the callback and its state variables meaningful names:

let t = null;
function h() {
  clearTimeout(t);
  t = setTimeout(() => {
    console.log('searching', i);
    fetch('/q?q=' + i);
  }, 300);
}
input.addEventListener('input', h);

output:
let debounceTimer = null;
function handleSearchInput() {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(() => {
    console.log('searching', query);
    fetch('/q?q=' + query);
  }, 300);
}
input.addEventListener('input', handleSearchInput);

What changed: h -> handleSearchInput, t -> debounceTimer, i -> query; the reader now sees a debounced search without opening a design doc.

