Refactor this code by renaming the boolean flag so its meaning at call sites is explicit:

def fetch_orders(uid, flag):
    q = 'SELECT * FROM orders'
    args = [uid]
    if flag:
        q += ' WHERE user_id = ? AND archived = 0'
    else:
        q += ' WHERE user_id = ?'
    return db.query(q, *args)

output:
def fetch_orders(uid, include_archived=False):
    if include_archived:
        q = 'SELECT * FROM orders WHERE user_id = ?'
    else:
        q = 'SELECT * FROM orders WHERE user_id = ? AND archived = 0'
    return db.query(q, uid)

What changed: flag -> include_archived with a default; call sites now read fetch_orders(uid, include_archived=True) instead of fetch_orders(uid, True).

def get(url):
    response = requests.get(url)
    if response.status_code != 200:
        return []
    payload = response.json()
    return payload.get('data', [])

What changed: r/res/rr -> response/payload/data and the condition was inverted for an early return, so each name maps to one layer of the HTTP exchange.

